import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { MatChip, MatChipAvatar } from '@angular/material/chips';
import { MatIcon } from '@angular/material/icon';
import { AitIconRegistry } from '../core/icons';

/**
 * AI chip — marks content a model produced (`ai-container` + sparkle). Only AI features may use it.
 * `<ait-ai-chip>Generated by ui-design</ait-ai-chip>`
 */
@Component({
  selector: 'ait-ai-chip',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [MatChip, MatChipAvatar, MatIcon],
  host: { class: 'ait-ai-chip' },
  template: `
    <mat-chip class="dt-ai ait-ai" [disableRipple]="true">
      <mat-icon matChipAvatar svgIcon="ait:sparkle" aria-hidden="true" />
      <ng-content />
    </mat-chip>
  `,
  styles: `
    :host { display: inline-flex; vertical-align: middle; }
    :host .mat-mdc-standard-chip.ait-ai {
      --mat-chip-with-avatar-avatar-size: 18px; --mat-chip-outline-width: 0;
      --mat-chip-elevated-container-color: var(--md-sys-color-ai-container); --mat-chip-label-text-color: var(--md-sys-color-on-ai-container);
      cursor: default;
    }
    mat-icon { width: 18px; height: 18px; color: var(--md-sys-color-on-ai-container); }
  `,
})
export class AitAiChip {
  constructor() {
    inject(AitIconRegistry);
  }
}
